<section class="profile-hero panel glass section"><?= avatar($profile,'large') ?><div class="grow"><span class="eyebrow">PEOPLE OF CHENGYU</span><h1><?= e($profile['display_name']) ?> <?= $profile['verified']?icon('shield'):'' ?></h1><p>@<?= e($profile['username']) ?> &middot; <?= nl2br(e($profile['bio'])) ?></p></div><div class="profile-actions row wrap"><?php if ($me && (int)$me['id']!==(int)$profile['id']): ?><?php if ($s->enabled('follows')): $following=(bool)$a->db->one('SELECT id FROM cy_follows WHERE follower_id=? AND followed_id=?',[(int)$me['id'],(int)$profile['id']]); ?><?= form_start('follow') . hidden('target_id',$profile['id']) ?><?php button($following?'Unfollow':'Follow','secondary',$following?'check':'plus'); ?></form><?php endif ?><?php if ($s->enabled('messages')): ?><a class="btn" href="<?= e(url('messages',['to'=>$profile['username']])) ?>"><?= icon('message') ?><?= t('Send a message') ?></a><?php endif ?><?php endif ?></div></section><?php partial('badge_collection',['badgeUser'=>(int)$profile['id']]); ?><?php if ($s->get('show_stats') && $s->enabled('follows')): ?><p class="hint section"><?= (int)$a->db->value('SELECT COUNT(*) FROM cy_follows WHERE followed_id=?',[(int)$profile['id']]) ?> <?= t('Followers') ?> &middot; <?= (int)$a->db->value('SELECT COUNT(*) FROM cy_follows WHERE follower_id=?',[(int)$profile['id']]) ?> <?= t('Following') ?></p><?php endif ?><div class="section-heading"><h2><?= t('Shared with the island') ?></h2></div><div class="card-grid"><?php foreach ($feed['items'] as $entry) {partial('card',['entry'=>$entry]);} ?></div><?php if (!$feed['items']) {empty_state();} partial('pagination',['feed'=>$feed,'route'=>$route]); ?>
